import os,subprocess
def describe_clone(repo):
    env={k:v for k,v in os.environ.items() if not k.startswith('GIT_')};env.update(GIT_CONFIG_NOSYSTEM='1',GIT_CONFIG_GLOBAL=os.devnull,GIT_TERMINAL_PROMPT='0',GIT_OPTIONAL_LOCKS='0')
    def git(*args,optional=False):
        p=subprocess.run(['git','-C',str(repo),*args],env=env,capture_output=True,text=True,timeout=5)
        if p.returncode and not (optional and p.returncode==1):raise RuntimeError('read-only clone evidence unavailable')
        return p.stdout.strip()
    shallow=git('rev-parse','--is-shallow-repository')=='true'
    promisor=git('config','--get','remote.origin.promisor',optional=True)=='true'
    history=int(git('rev-list','--count','HEAD'))
    objects=git('rev-list','--objects','--all','--no-object-names','--missing=print').splitlines()
    return {'shallow':shallow,'promisor':promisor,'history':history,'missing_objects':sum(line.startswith('?') for line in objects)}
